fn validate_print_out_args(args: &[OmValue], object_name: &str) -> OmResult<()> {
    if args.len() > 9 {
        return Err(OmError::invalid_argument(format!(
            "{object_name}.PrintOut accepts at most From, To, Copies, Preview, ActivePrinter, PrintToFile, Collate, PrToFileName, and IgnorePrintAreas arguments"
        )));
    }
    for (index, label) in ["From", "To", "Copies"].into_iter().enumerate() {
        if let Some(value) = args.get(index) {
            if om_value_is_omitted(value) {
                continue;
            }
            let label = format!("{object_name}.PrintOut {label}");
            coerce_u32_arg(value, &label)?;
        }
    }
    if let Some(value) = args.get(3) {
        let label = format!("{object_name}.PrintOut Preview");
        coerce_optional_bool_arg(value, false, &label)?;
    }
    if let Some(value) = args.get(4)
        && !om_value_is_omitted(value)
        && !matches!(value, OmValue::Text(_))
    {
        return Err(OmError::type_mismatch(format!(
            "{object_name}.PrintOut ActivePrinter must be text when provided"
        )));
    }
    if let Some(value) = args.get(5) {
        let label = format!("{object_name}.PrintOut PrintToFile");
        coerce_optional_bool_arg(value, false, &label)?;
    }
    if let Some(value) = args.get(6) {
        let label = format!("{object_name}.PrintOut Collate");
        coerce_optional_bool_arg(value, false, &label)?;
    }
    if let Some(value) = args.get(7)
        && !om_value_is_omitted(value)
        && !matches!(value, OmValue::Text(_))
    {
        return Err(OmError::type_mismatch(format!(
            "{object_name}.PrintOut PrToFileName must be text when provided"
        )));
    }
    if let Some(value) = args.get(8) {
        let label = format!("{object_name}.PrintOut IgnorePrintAreas");
        coerce_optional_bool_arg(value, false, &label)?;
    }
    Ok(())
}

fn sheet_visibility_to_excel_value(visibility: SheetVisibility) -> i32 {
    match visibility {
        SheetVisibility::Visible => XL_SHEET_VISIBLE,
        SheetVisibility::Hidden => XL_SHEET_HIDDEN,
        SheetVisibility::VeryHidden => XL_SHEET_VERY_HIDDEN,
    }
}

fn coerce_sheet_visibility(value: OmValue) -> OmResult<SheetVisibility> {
    match value {
        OmValue::Bool(true) => Ok(SheetVisibility::Visible),
        OmValue::Bool(false) => Ok(SheetVisibility::Hidden),
        OmValue::Number(number) => {
            if !number.is_finite()
                || number.fract() != 0.0
                || number < i32::MIN as f64
                || number > i32::MAX as f64
            {
                return Err(OmError::invalid_argument(
                    "Worksheet.Visible expects an integral XlSheetVisibility value",
                ));
            }
            match number as i32 {
                XL_SHEET_VISIBLE => Ok(SheetVisibility::Visible),
                XL_SHEET_HIDDEN => Ok(SheetVisibility::Hidden),
                XL_SHEET_VERY_HIDDEN => Ok(SheetVisibility::VeryHidden),
                _ => Err(OmError::invalid_argument(
                    "Worksheet.Visible supports xlSheetVisible, xlSheetHidden, and xlSheetVeryHidden",
                )),
            }
        }
        _ => Err(OmError::type_mismatch(
            "Worksheet.Visible expects a boolean or XlSheetVisibility numeric value",
        )),
    }
}

fn coerce_cut_copy_mode(value: OmValue) -> OmResult<Option<i32>> {
    match value {
        OmValue::Bool(false) => Ok(None),
        OmValue::Bool(true) => Err(OmError::invalid_argument(
            "Application.CutCopyMode expects false, xlCopy, or xlCut",
        )),
        OmValue::Number(number) => {
            if !number.is_finite()
                || number.fract() != 0.0
                || number < i32::MIN as f64
                || number > i32::MAX as f64
            {
                return Err(OmError::invalid_argument(
                    "Application.CutCopyMode expects an integral XlCutCopyMode value",
                ));
            }
            match number as i32 {
                XL_COPY => Ok(Some(XL_COPY)),
                XL_CUT => Ok(Some(XL_CUT)),
                _ => Err(OmError::invalid_argument(
                    "Application.CutCopyMode supports xlCopy and xlCut numeric values",
                )),
            }
        }
        _ => Err(OmError::type_mismatch(
            "Application.CutCopyMode expects false or an XlCutCopyMode numeric value",
        )),
    }
}

fn format_find_number(number: f64) -> String {
    if number.is_finite()
        && number.fract() == 0.0
        && number >= i64::MIN as f64
        && number <= i64::MAX as f64
    {
        (number as i64).to_string()
    } else {
        number.to_string()
    }
}

fn find_cell_value_text(value: &CellValue) -> String {
    match value {
        CellValue::Blank => String::new(),
        CellValue::Bool(true) => "TRUE".to_string(),
        CellValue::Bool(false) => "FALSE".to_string(),
        CellValue::Number(number) => format_find_number(*number),
        CellValue::Text(text) => text.clone(),
        CellValue::Error(error) => formula_cell_error_text(*error).to_string(),
    }
}

fn file_format_to_excel_value(format: FileFormat) -> i32 {
    match format {
        FileFormat::Xlsx => XL_OPEN_XML_WORKBOOK,
        FileFormat::Xlsm => XL_OPEN_XML_WORKBOOK_MACRO_ENABLED,
        FileFormat::Xltx => XL_OPEN_XML_TEMPLATE,
        FileFormat::Xltm => XL_OPEN_XML_TEMPLATE_MACRO_ENABLED,
        FileFormat::StrictXlsx => XL_OPEN_XML_STRICT_WORKBOOK,
    }
}

fn file_format_from_path(path: &Path) -> Option<FileFormat> {
    match path
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.to_ascii_lowercase())
        .as_deref()
    {
        Some("xlsx") => Some(FileFormat::Xlsx),
        Some("xlsm") => Some(FileFormat::Xlsm),
        Some("xltx") => Some(FileFormat::Xltx),
        Some("xltm") => Some(FileFormat::Xltm),
        _ => None,
    }
}

fn workbook_main_content_type(format: FileFormat) -> OmResult<&'static str> {
    match format {
        FileFormat::Xlsx => Ok(WORKBOOK_XLSX_CONTENT_TYPE),
        FileFormat::Xlsm => Ok(WORKBOOK_XLSM_CONTENT_TYPE),
        FileFormat::Xltx => Ok(WORKBOOK_XLTX_CONTENT_TYPE),
        FileFormat::Xltm => Ok(WORKBOOK_XLTM_CONTENT_TYPE),
        FileFormat::StrictXlsx => Err(OmError::unsupported(
            "strict OOXML workbook save conversion is not implemented",
        )),
    }
}

fn format_allows_vba_project(format: FileFormat) -> bool {
    matches!(format, FileFormat::Xlsm | FileFormat::Xltm)
}

fn retag_loaded_workbook_format(
    loaded: &LoadedXlsxWorkbook,
    format: FileFormat,
) -> OmResult<LoadedXlsxWorkbook> {
    if format == loaded.detected_format && loaded.state.model.format == format {
        return Ok(loaded.clone());
    }
    let content_type = workbook_main_content_type(format)?;

    let mut retagged = loaded.clone();
    let mut content_types_xml = retagged
        .package
        .part(CONTENT_TYPES_PART_NAME)
        .ok_or_else(|| {
            OmError::new(
                OmErrorCode::Parse,
                format!("workbook package is missing {CONTENT_TYPES_PART_NAME}"),
            )
        })?
        .bytes
        .clone();
    if retagged.package.contains(VBA_PROJECT_PART_NAME) && !format_allows_vba_project(format) {
        retagged.package.remove_part(VBA_PROJECT_PART_NAME);
        content_types_xml = strip_content_type_overrides(
            content_types_xml.as_slice(),
            &[VBA_PROJECT_PART_NAME.to_string()],
        )?;
        content_types_xml = strip_content_type_defaults_by_content_type(
            content_types_xml.as_slice(),
            &[VBA_PROJECT_CONTENT_TYPE],
        )?;
        let workbook_rels_part_name = retagged
            .support_parts
            .workbook_relationships_part_uri
            .clone()
            .unwrap_or_else(|| WORKBOOK_RELS_PART_NAME.to_string());
        if let Some(workbook_rels_xml) = retagged
            .package
            .part(workbook_rels_part_name.as_str())
            .map(|part| part.bytes.clone())
        {
            retagged.package.replace_part_bytes(
                workbook_rels_part_name.as_str(),
                strip_relationship_entries_by_type_or_target(
                    workbook_rels_xml.as_slice(),
                    &[VBA_PROJECT_RELATIONSHIP_TYPE],
                    &[VBA_PROJECT_PART_NAME, "vbaProject.bin"],
                )?,
            )?;
        }
    }
    let content_types_xml = set_content_type_override(
        content_types_xml.as_slice(),
        WORKBOOK_PART_NAME,
        content_type,
    )?;
    retagged
        .package
        .replace_part_bytes(CONTENT_TYPES_PART_NAME, content_types_xml)?;
    retagged.package =
        retag_package_part_content_type(retagged.package, WORKBOOK_PART_NAME, content_type);
    retagged.detected_format = format;
    retagged.state.model.format = format;
    Ok(retagged)
}

fn retag_package_part_content_type(
    package: OpcPackage,
    part_name: &str,
    content_type: &str,
) -> OpcPackage {
    let normalized_part_name = part_name.trim_start_matches('/');
    let mut parts = package.parts().to_vec();
    for part in &mut parts {
        if part.name == normalized_part_name {
            part.content_type = Some(content_type.to_string());
        }
    }
    OpcPackage::new(parts)
}

fn runtime_xml_error(error: impl std::fmt::Display) -> OmError {
    OmError::new(OmErrorCode::Parse, error.to_string())
}

fn append_empty_xml_child_before_container_end(
    xml: &[u8],
    container_name: &[u8],
    child: BytesStart<'static>,
) -> OmResult<Vec<u8>> {
    let mut reader = Reader::from_reader(Cursor::new(xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut container_seen = false;
    let qualify_child = |container_qualified_name: &[u8]| -> OmResult<BytesStart<'static>> {
        let child_name = child.name();
        let local_name = String::from_utf8_lossy(xml_local_name(child_name.as_ref())).into_owned();
        let qualified_name = if let Some(separator) = container_qualified_name
            .iter()
            .position(|byte| *byte == b':')
        {
            format!(
                "{}:{local_name}",
                String::from_utf8_lossy(&container_qualified_name[..separator])
            )
        } else {
            local_name
        };
        let mut qualified = BytesStart::new(qualified_name);
        for attr in child.attributes().with_checks(false) {
            let attr = attr.map_err(runtime_xml_error)?;
            let key = attr.key.as_ref().to_vec();
            let value = attr.value.into_owned();
            qualified.push_attribute((key.as_slice(), value.as_slice()));
        }
        Ok(qualified)
    };

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == container_name =>
            {
                container_seen = true;
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == container_name =>
            {
                container_seen = true;
                let container_qualified_name = element.name().as_ref().to_vec();
                let qualified_name = String::from_utf8_lossy(element.name().as_ref()).into_owned();
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
                writer
                    .write_event(Event::Empty(qualify_child(&container_qualified_name)?))
                    .map_err(runtime_xml_error)?;
                writer
                    .write_event(Event::End(BytesEnd::new(qualified_name)))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::End(element))
                if xml_local_name(element.name().as_ref()) == container_name =>
            {
                if !container_seen {
                    return Err(OmError::new(
                        OmErrorCode::Parse,
                        format!(
                            "XML container {} was not found",
                            String::from_utf8_lossy(container_name)
                        ),
                    ));
                }
                writer
                    .write_event(Event::Empty(qualify_child(element.name().as_ref())?))
                    .map_err(runtime_xml_error)?;
                writer
                    .write_event(Event::End(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Eof) => break,
            Ok(event) => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    if !container_seen {
        return Err(OmError::new(
            OmErrorCode::Parse,
            format!(
                "XML container {} was not found",
                String::from_utf8_lossy(container_name)
            ),
        ));
    }

    Ok(writer.into_inner().into_inner())
}

struct MaterializedChartSupportRelationships {
    relationship_bytes: Vec<u8>,
    relationships: Vec<ChartSupportRelationshipBinding>,
    part_bytes: BTreeMap<String, Vec<u8>>,
    content_types_dirty: bool,
}

fn materialize_chart_support_relationships(
    package: &mut OpcPackage,
    chart_part_uri: &str,
    mut relationship_bytes: Vec<u8>,
    mut content_types_xml: Vec<u8>,
    used_part_names: &mut BTreeSet<String>,
    sources: &[RuntimeChartSupportPartSource],
) -> OmResult<(MaterializedChartSupportRelationships, Vec<u8>)> {
    let mut used_relationship_ids = parse_pending_package_relationships(
        relationship_bytes.as_slice(),
        chart_part_uri,
    )?
    .into_iter()
    .map(|relationship| relationship.relationship_id)
    .collect::<BTreeSet<_>>();
    let mut relationships = Vec::with_capacity(sources.len());
    let mut part_bytes = BTreeMap::new();
    let mut content_types_dirty = false;

    for source in sources {
        if !used_relationship_ids.insert(source.relationship_id.clone()) {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                format!(
                    "chart relationship id is duplicated while copying support parts: {}",
                    source.relationship_id
                ),
            ));
        }
        let external = source
            .target_mode
            .as_deref()
            .is_some_and(|target_mode| target_mode.eq_ignore_ascii_case("External"));
        let (relationship_target, materialized_target) = match (&source.part, external) {
            (None, true) => (source.target.clone(), source.target.clone()),
            (Some(_), true) => {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "external chart support relationship unexpectedly owns a package part",
                ));
            }
            (None, false) => {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    format!("chart support part is missing: {}", source.target),
                ));
            }
            (Some(part), false) => {
                let file_name = source
                    .target
                    .rsplit('/')
                    .next()
                    .unwrap_or(source.target.as_str());
                let target_part_uri = if source.relationship_type
                    == CHART_COLOR_STYLE_RELATIONSHIP_TYPE
                    || file_name.starts_with("colors")
                {
                    next_available_sequential_part_uri(
                        used_part_names,
                        "xl/charts/colors",
                        ".xml",
                    )
                } else {
                    next_available_sequential_part_uri(
                        used_part_names,
                        "xl/charts/style",
                        ".xml",
                    )
                };
                package.add_part(OpcPart {
                    name: target_part_uri.clone(),
                    content_type: part.content_type.clone(),
                    compression: part.compression,
                    bytes: part.bytes.clone(),
                })?;
                if let Some(content_type) = part.content_type.as_deref() {
                    content_types_xml = append_content_type_override_if_missing(
                        content_types_xml.as_slice(),
                        target_part_uri.as_str(),
                        content_type,
                    )?;
                    content_types_dirty = true;
                }
                part_bytes.insert(target_part_uri.clone(), part.bytes.clone());
                (
                    relative_relationship_target(chart_part_uri, &target_part_uri),
                    target_part_uri,
                )
            }
        };

        let mut relationship = BytesStart::new("Relationship");
        relationship.push_attribute(("Id", source.relationship_id.as_str()));
        relationship.push_attribute(("Type", source.relationship_type.as_str()));
        relationship.push_attribute(("Target", relationship_target.as_str()));
        if let Some(target_mode) = source.target_mode.as_deref() {
            relationship.push_attribute(("TargetMode", target_mode));
        }
        relationship_bytes = append_empty_xml_child_before_container_end(
            relationship_bytes.as_slice(),
            b"Relationships",
            relationship,
        )?;
        relationships.push(ChartSupportRelationshipBinding {
            relationship_id: source.relationship_id.clone(),
            relationship_type: source.relationship_type.clone(),
            target: materialized_target,
            target_mode: source.target_mode.clone(),
        });
    }

    Ok((
        MaterializedChartSupportRelationships {
            relationship_bytes,
            relationships,
            part_bytes,
            content_types_dirty,
        },
        content_types_xml,
    ))
}

fn pending_package_relationship_is_external(relationship: &PendingPackageRelationship) -> bool {
    relationship
        .target_mode
        .as_deref()
        .is_some_and(|target_mode| target_mode.eq_ignore_ascii_case("External"))
}

fn validate_pending_runtime_relationship(
    relationship: &PendingPackageRelationship,
) -> OmResult<()> {
    if relationship.relationship_id.trim().is_empty()
        || relationship.relationship_type.trim().is_empty()
        || relationship.target.trim().is_empty()
    {
        return Err(OmError::new(
            OmErrorCode::InvalidState,
            "opaque package relationship requires an id, type, and target",
        ));
    }
    if relationship
        .target_mode
        .as_deref()
        .is_some_and(|mode| {
            !mode.eq_ignore_ascii_case("External") && !mode.eq_ignore_ascii_case("Internal")
        })
    {
        return Err(OmError::new(
            OmErrorCode::InvalidState,
            format!(
                "opaque package relationship {} has unsupported TargetMode",
                relationship.relationship_id
            ),
        ));
    }
    Ok(())
}

fn collect_pending_package_part_graph(
    package: &OpcPackage,
    source_part_uri: &str,
    parts: &mut BTreeMap<String, PendingPackagePart>,
) -> OmResult<()> {
    if parts.contains_key(source_part_uri) {
        return Ok(());
    }
    let source_part = package.part(source_part_uri).ok_or_else(|| {
        OmError::new(
            OmErrorCode::InvalidState,
            format!("opaque relationship target part is missing: {source_part_uri}"),
        )
    })?;
    let relationships_part_uri = worksheet_relationships_part_uri_for(source_part_uri);
    let relationships_part = package.part(&relationships_part_uri);
    let relationships = relationships_part
        .map(|part| {
            parse_pending_package_relationships(part.bytes.as_slice(), source_part_uri)
        })
        .transpose()?
        .unwrap_or_default();
    parts.insert(
        source_part_uri.to_string(),
        PendingPackagePart {
            source_part_uri: source_part_uri.to_string(),
            bytes: source_part.bytes.clone(),
            content_type: source_part.content_type.clone(),
            compression: source_part.compression,
            relationships_part_source_bytes: relationships_part.map(|part| part.bytes.clone()),
            relationships_part_compression: relationships_part.map(|part| part.compression),
            relationships: relationships.clone(),
        },
    );
    for relationship in relationships {
        if !pending_package_relationship_is_external(&relationship) {
            collect_pending_package_part_graph(package, &relationship.target, parts)?;
        }
    }
    Ok(())
}

fn exclusively_owned_package_graph_part_uris(
    package: &OpcPackage,
    removed_owner_part_uris: &BTreeSet<String>,
    part_graphs: &[&BTreeMap<String, PendingPackagePart>],
) -> OmResult<BTreeSet<String>> {
    let mut candidate_parts = BTreeMap::<String, &PendingPackagePart>::new();
    for graph in part_graphs {
        for (part_uri, part) in *graph {
            candidate_parts.entry(part_uri.clone()).or_insert(part);
        }
    }
    if candidate_parts.is_empty() {
        return Ok(BTreeSet::new());
    }
    let candidate_part_uris = candidate_parts.keys().cloned().collect::<BTreeSet<_>>();
    let mut shared_roots = BTreeSet::new();

    for relationships_part in package
        .parts()
        .iter()
        .filter(|part| part.name.ends_with(".rels"))
    {
        let owner_part_uri = if relationships_part.name == "_rels/.rels" {
            String::new()
        } else if let Some((parent, relationships_file_name)) =
            relationships_part.name.rsplit_once("/_rels/")
            && let Some(file_name) = relationships_file_name.strip_suffix(".rels")
        {
            format!("{parent}/{file_name}")
        } else {
            continue;
        };
        if removed_owner_part_uris.contains(&owner_part_uri)
            || candidate_part_uris.contains(&owner_part_uri)
        {
            continue;
        }
        for relationship in parse_pending_package_relationships(
            relationships_part.bytes.as_slice(),
            owner_part_uri.as_str(),
        )? {
            if !pending_package_relationship_is_external(&relationship)
                && candidate_part_uris.contains(&relationship.target)
            {
                shared_roots.insert(relationship.target);
            }
        }
    }

    let mut preserved_part_uris = BTreeSet::new();
    let mut pending = shared_roots.into_iter().collect::<Vec<_>>();
    while let Some(part_uri) = pending.pop() {
        if !preserved_part_uris.insert(part_uri.clone()) {
            continue;
        }
        let Some(part) = candidate_parts.get(&part_uri) else {
            continue;
        };
        for relationship in &part.relationships {
            if !pending_package_relationship_is_external(relationship)
                && candidate_part_uris.contains(&relationship.target)
            {
                pending.push(relationship.target.clone());
            }
        }
    }

    Ok(candidate_part_uris
        .difference(&preserved_part_uris)
        .cloned()
        .collect())
}

fn parse_pending_package_relationships(
    relationships_xml: &[u8],
    source_part_uri: &str,
) -> OmResult<Vec<PendingPackageRelationship>> {
    let mut reader = Reader::from_reader(Cursor::new(relationships_xml));
    reader.config_mut().trim_text(true);
    let mut buffer = Vec::new();
    let mut relationships = Vec::new();
    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(element)) | Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship" =>
            {
                let mut relationship_id = None;
                let mut relationship_type = None;
                let mut target = None;
                let mut target_mode = None;
                for attr in element.attributes() {
                    let attr = attr.map_err(runtime_xml_error)?;
                    let value = attr
                        .decode_and_unescape_value(reader.decoder())
                        .map_err(runtime_xml_error)?
                        .into_owned();
                    match attr.key.as_ref() {
                        b"Id" => relationship_id = Some(value),
                        b"Type" => relationship_type = Some(value),
                        b"Target" => target = Some(value),
                        b"TargetMode" => target_mode = Some(value),
                        _ => {}
                    }
                }
                let relationship_id = relationship_id.ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        format!(
                            "relationship in {} has no Id",
                            worksheet_relationships_part_uri_for(source_part_uri)
                        ),
                    )
                })?;
                let relationship_type = relationship_type.ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        format!("relationship {relationship_id} has no Type"),
                    )
                })?;
                let target = target.ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        format!("relationship {relationship_id} has no Target"),
                    )
                })?;
                let external = target_mode
                    .as_deref()
                    .is_some_and(|mode| mode.eq_ignore_ascii_case("External"));
                let target = if external {
                    target
                } else {
                    normalize_pending_package_target(&target, source_part_uri).ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::InvalidState,
                            format!(
                                "relationship {relationship_id} has an invalid internal Target"
                            ),
                        )
                    })?
                };
                relationships.push(PendingPackageRelationship {
                    relationship_id,
                    relationship_type,
                    target,
                    target_mode,
                });
                validate_pending_runtime_relationship(
                    relationships.last().expect("relationship pushed above"),
                )?;
            }
            Ok(Event::Eof) => break,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }
    Ok(relationships)
}

fn normalize_pending_package_target(target: &str, source_part_uri: &str) -> Option<String> {
    let mut segments = if target.starts_with('/') {
        Vec::new()
    } else {
        source_part_uri
            .rsplit_once('/')
            .map_or("", |(parent, _)| parent)
            .split('/')
            .filter(|segment| !segment.is_empty())
            .map(str::to_string)
            .collect::<Vec<_>>()
    };
    for segment in target.split('/') {
        match segment {
            "" | "." => {}
            ".." => {
                segments.pop();
            }
            _ => segments.push(segment.to_string()),
        }
    }
    (!segments.is_empty()).then(|| segments.join("/"))
}

fn worksheet_relationships_part_uri_for(worksheet_part_uri: &str) -> String {
    if let Some((prefix, file_name)) = worksheet_part_uri.rsplit_once('/') {
        format!("{prefix}/_rels/{file_name}.rels")
    } else {
        format!("_rels/{worksheet_part_uri}.rels")
    }
}

fn next_available_sequential_part_uri(
    used_part_names: &mut BTreeSet<String>,
    prefix: &str,
    suffix: &str,
) -> String {
    let mut index = 1usize;
    loop {
        let candidate = format!("{prefix}{index}{suffix}");
        if used_part_names.insert(candidate.clone()) {
            return candidate;
        }
        index += 1;
    }
}

fn unique_worksheet_name_with_prefix(worksheets: &[WorksheetModel], prefix: &str) -> String {
    (1..)
        .find_map(|index| {
            let candidate = format!("{prefix}{index}");
            (!worksheets
                .iter()
                .any(|worksheet| worksheet.name.eq_ignore_ascii_case(candidate.as_str())))
            .then_some(candidate)
        })
        .expect("worksheet name index")
}

fn relative_relationship_target(worksheet_part_uri: &str, target_part_uri: &str) -> String {
    let Some((parent, _)) = worksheet_part_uri.rsplit_once('/') else {
        return target_part_uri.to_string();
    };
    let base_segments = parent
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    let target_segments = target_part_uri
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    let shared_prefix_len = base_segments
        .iter()
        .zip(target_segments.iter())
        .take_while(|(lhs, rhs)| lhs == rhs)
        .count();
    let mut relative_segments = vec![".."; base_segments.len().saturating_sub(shared_prefix_len)];
    relative_segments.extend_from_slice(&target_segments[shared_prefix_len..]);
    if relative_segments.is_empty() {
        target_part_uri.to_string()
    } else {
        relative_segments.join("/")
    }
}

fn rewrite_relationship_targets(
    rels_xml: &[u8],
    rewritten_targets: &BTreeMap<String, String>,
    worksheet_part_uri: &str,
) -> OmResult<Vec<u8>> {
    let mut reader = Reader::from_reader(Cursor::new(rels_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship" =>
            {
                writer
                    .write_event(Event::Start(rewrite_relationship_target(
                        &element,
                        reader.decoder(),
                        rewritten_targets,
                        worksheet_part_uri,
                    )?))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship" =>
            {
                writer
                    .write_event(Event::Empty(rewrite_relationship_target(
                        &element,
                        reader.decoder(),
                        rewritten_targets,
                        worksheet_part_uri,
                    )?))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Eof) => {
                writer.write_event(Event::Eof).map_err(runtime_xml_error)?;
                break;
            }
            Ok(event) => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn rewrite_relationship_target(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    rewritten_targets: &BTreeMap<String, String>,
    worksheet_part_uri: &str,
) -> OmResult<BytesStart<'static>> {
    let mut relationship_id = None::<String>;
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        if attr.key.as_ref() == b"Id" {
            relationship_id = Some(
                attr.decode_and_unescape_value(decoder)
                    .map_err(runtime_xml_error)?
                    .into_owned(),
            );
            break;
        }
    }
    let Some(relationship_id) = relationship_id else {
        return Ok(element.to_owned());
    };
    let Some(target_part_uri) = rewritten_targets.get(&relationship_id) else {
        return Ok(element.to_owned());
    };
    let target = relative_relationship_target(worksheet_part_uri, target_part_uri);

    let qualified_name = String::from_utf8_lossy(element.name().as_ref()).into_owned();
    let mut rewritten = BytesStart::new(qualified_name);
    let mut saw_target = false;
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        let key = String::from_utf8_lossy(attr.key.as_ref()).into_owned();
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        let value = if attr.key.as_ref() == b"Target" {
            saw_target = true;
            target.as_str()
        } else {
            value.as_str()
        };
        rewritten.push_attribute((key.as_str(), value));
    }
    if !saw_target {
        rewritten.push_attribute(("Target", target.as_str()));
    }
    Ok(rewritten)
}

fn content_types_has_override(content_types_xml: &[u8], part_uri: &str) -> OmResult<bool> {
    let wanted_part_name = format!("/{}", part_uri.trim_start_matches('/'));
    let mut reader = Reader::from_reader(Cursor::new(content_types_xml));
    reader.config_mut().trim_text(false);
    let mut buffer = Vec::new();

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(element)) | Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Override" =>
            {
                for attr in element.attributes() {
                    let attr = attr.map_err(runtime_xml_error)?;
                    if attr.key.as_ref() != b"PartName" {
                        continue;
                    }
                    let value = attr
                        .decode_and_unescape_value(reader.decoder())
                        .map_err(runtime_xml_error)?
                        .into_owned();
                    if value == wanted_part_name {
                        return Ok(true);
                    }
                }
            }
            Ok(Event::Eof) => return Ok(false),
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }
}

fn content_types_has_default(
    content_types_xml: &[u8],
    extension: &str,
    content_type: &str,
) -> OmResult<bool> {
    let mut reader = Reader::from_reader(Cursor::new(content_types_xml));
    reader.config_mut().trim_text(false);
    let mut buffer = Vec::new();

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(element)) | Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Default" =>
            {
                let mut seen_extension = false;
                let mut seen_content_type = false;
                for attr in element.attributes() {
                    let attr = attr.map_err(runtime_xml_error)?;
                    let value = attr
                        .decode_and_unescape_value(reader.decoder())
                        .map_err(runtime_xml_error)?
                        .into_owned();
                    match attr.key.as_ref() {
                        b"Extension" if value == extension => seen_extension = true,
                        b"ContentType" if value == content_type => seen_content_type = true,
                        _ => {}
                    }
                }
                if seen_extension && seen_content_type {
                    return Ok(true);
                }
            }
            Ok(Event::Eof) => return Ok(false),
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }
}

fn append_content_type_override_if_missing(
    content_types_xml: &[u8],
    part_uri: &str,
    content_type: &str,
) -> OmResult<Vec<u8>> {
    if content_types_has_override(content_types_xml, part_uri)? {
        return Ok(content_types_xml.to_vec());
    }
    append_empty_xml_child_before_container_end(content_types_xml, b"Types", {
        let mut element = BytesStart::new("Override");
        element.push_attribute((
            "PartName",
            format!("/{}", part_uri.trim_start_matches('/')).as_str(),
        ));
        element.push_attribute(("ContentType", content_type));
        element
    })
}

fn append_content_type_default_if_missing(
    content_types_xml: &[u8],
    extension: &str,
    content_type: &str,
) -> OmResult<Vec<u8>> {
    if content_types_has_default(content_types_xml, extension, content_type)? {
        return Ok(content_types_xml.to_vec());
    }
    append_empty_xml_child_before_container_end(content_types_xml, b"Types", {
        let mut element = BytesStart::new("Default");
        element.push_attribute(("Extension", extension));
        element.push_attribute(("ContentType", content_type));
        element
    })
}

fn set_content_type_override(
    content_types_xml: &[u8],
    part_uri: &str,
    content_type: &str,
) -> OmResult<Vec<u8>> {
    let wanted_part_name = format!("/{}", part_uri.trim_start_matches('/'));
    let mut reader = Reader::from_reader(Cursor::new(content_types_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut found = false;

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Override"
                    && content_type_override_matches_part(
                        &element,
                        reader.decoder(),
                        wanted_part_name.as_str(),
                    )? =>
            {
                found = true;
                writer
                    .write_event(Event::Empty(rewrite_content_type_override_element(
                        &element,
                        reader.decoder(),
                        content_type,
                    )?))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"Override"
                    && content_type_override_matches_part(
                        &element,
                        reader.decoder(),
                        wanted_part_name.as_str(),
                    )? =>
            {
                found = true;
                writer
                    .write_event(Event::Start(rewrite_content_type_override_element(
                        &element,
                        reader.decoder(),
                        content_type,
                    )?))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Eof) => break,
            Ok(event) => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    let content_types_xml = writer.into_inner().into_inner();
    if found {
        Ok(content_types_xml)
    } else {
        append_content_type_override_if_missing(
            content_types_xml.as_slice(),
            part_uri,
            content_type,
        )
    }
}

fn content_type_override_matches_part(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    part_name: &str,
) -> OmResult<bool> {
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        if attr.key.as_ref() != b"PartName" {
            continue;
        }
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        return Ok(value == part_name);
    }
    Ok(false)
}

fn rewrite_content_type_override_element(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    content_type: &str,
) -> OmResult<BytesStart<'static>> {
    let mut rewritten =
        BytesStart::new(String::from_utf8_lossy(element.name().as_ref()).into_owned());
    let mut saw_content_type = false;
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        let key = String::from_utf8_lossy(attr.key.as_ref()).into_owned();
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        if attr.key.as_ref() == b"ContentType" {
            saw_content_type = true;
            rewritten.push_attribute((key.as_str(), content_type));
        } else {
            rewritten.push_attribute((key.as_str(), value.as_str()));
        }
    }
    if !saw_content_type {
        rewritten.push_attribute(("ContentType", content_type));
    }
    Ok(rewritten)
}

fn insert_sheet_into_workbook_xml(
    workbook_xml: &[u8],
    insert_at: usize,
    worksheet_name: &str,
    sheet_id: SheetId,
    relationship_id: &str,
) -> OmResult<Vec<u8>> {
    let mut reader = Reader::from_reader(Cursor::new(workbook_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut sheets_seen = false;
    let mut inside_sheets = false;
    let mut sheets_depth = 0usize;
    let mut sheet_index = 0usize;
    let mut inserted = false;

    let mut inserted_sheet = BytesStart::new("sheet");
    inserted_sheet.push_attribute(("name", worksheet_name));
    inserted_sheet.push_attribute(("sheetId", sheet_id.0.to_string().as_str()));
    inserted_sheet.push_attribute(("r:id", relationship_id));

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(element)) if xml_local_name(element.name().as_ref()) == b"sheets" => {
                sheets_seen = true;
                inside_sheets = true;
                sheets_depth = 1;
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Empty(element)) if xml_local_name(element.name().as_ref()) == b"sheets" => {
                sheets_seen = true;
                inserted = true;
                let qualified_name = String::from_utf8_lossy(element.name().as_ref()).into_owned();
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
                writer
                    .write_event(Event::Empty(inserted_sheet.clone()))
                    .map_err(runtime_xml_error)?;
                writer
                    .write_event(Event::End(BytesEnd::new(qualified_name)))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Start(element))
                if inside_sheets
                    && sheets_depth == 1
                    && xml_local_name(element.name().as_ref()) == b"sheet" =>
            {
                if !inserted && sheet_index == insert_at {
                    writer
                        .write_event(Event::Empty(inserted_sheet.clone()))
                        .map_err(runtime_xml_error)?;
                    inserted = true;
                }
                sheet_index += 1;
                sheets_depth += 1;
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Empty(element))
                if inside_sheets
                    && sheets_depth == 1
                    && xml_local_name(element.name().as_ref()) == b"sheet" =>
            {
                if !inserted && sheet_index == insert_at {
                    writer
                        .write_event(Event::Empty(inserted_sheet.clone()))
                        .map_err(runtime_xml_error)?;
                    inserted = true;
                }
                sheet_index += 1;
                writer
                    .write_event(Event::Empty(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Start(element)) => {
                if inside_sheets {
                    sheets_depth += 1;
                }
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::End(element)) if inside_sheets && sheets_depth == 1 => {
                if !inserted {
                    writer
                        .write_event(Event::Empty(inserted_sheet.clone()))
                        .map_err(runtime_xml_error)?;
                    inserted = true;
                }
                inside_sheets = false;
                sheets_depth = 0;
                writer
                    .write_event(Event::End(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::End(element)) => {
                if inside_sheets && sheets_depth > 0 {
                    sheets_depth -= 1;
                }
                writer
                    .write_event(Event::End(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Eof) => break,
            Ok(event) => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    if !sheets_seen {
        return Err(OmError::new(
            OmErrorCode::Parse,
            "workbook.xml does not contain a sheets container",
        ));
    }

    Ok(writer.into_inner().into_inner())
}

fn reorder_workbook_sheet_entries(
    workbook_xml: &[u8],
    worksheets: &[WorksheetModel],
) -> OmResult<Vec<u8>> {
    let mut reader = Reader::from_reader(Cursor::new(workbook_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut inside_sheets = false;
    let mut skip_sheet_depth = 0usize;
    let mut sheet_entries = Vec::<(SheetId, Option<String>, BytesStart<'static>)>::new();

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(_)) if skip_sheet_depth > 0 => {
                skip_sheet_depth += 1;
            }
            Ok(Event::End(_)) if skip_sheet_depth > 0 => {
                skip_sheet_depth -= 1;
            }
            Ok(Event::Start(element)) if xml_local_name(element.name().as_ref()) == b"sheets" => {
                inside_sheets = true;
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Empty(element)) if xml_local_name(element.name().as_ref()) == b"sheets" => {
                let qualified_name = String::from_utf8_lossy(element.name().as_ref()).into_owned();
                writer
                    .write_event(Event::Start(element.into_owned()))
                    .map_err(runtime_xml_error)?;
                for worksheet in worksheets {
                    let entry = sheet_entries
                        .iter()
                        .find(|(entry_sheet_id, entry_relationship_id, _)| {
                            *entry_sheet_id == worksheet.id
                                || entry_relationship_id.as_deref()
                                    == worksheet.relationship_id.as_deref()
                        })
                        .ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::Parse,
                                format!(
                                    "workbook.xml is missing a sheet entry for {}",
                                    worksheet.name
                                ),
                            )
                        })?;
                    writer
                        .write_event(Event::Empty(entry.2.clone()))
                        .map_err(runtime_xml_error)?;
                }
                writer
                    .write_event(Event::End(BytesEnd::new(qualified_name)))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Empty(element))
                if inside_sheets && xml_local_name(element.name().as_ref()) == b"sheet" =>
            {
                sheet_entries.push(read_workbook_sheet_entry_identity(
                    &element,
                    reader.decoder(),
                )?);
            }
            Ok(Event::Start(element))
                if inside_sheets && xml_local_name(element.name().as_ref()) == b"sheet" =>
            {
                sheet_entries.push(read_workbook_sheet_entry_identity(
                    &element,
                    reader.decoder(),
                )?);
                skip_sheet_depth = 1;
            }
            Ok(Event::End(element))
                if inside_sheets && xml_local_name(element.name().as_ref()) == b"sheets" =>
            {
                for worksheet in worksheets {
                    let entry = sheet_entries
                        .iter()
                        .find(|(entry_sheet_id, entry_relationship_id, _)| {
                            *entry_sheet_id == worksheet.id
                                || entry_relationship_id.as_deref()
                                    == worksheet.relationship_id.as_deref()
                        })
                        .ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::Parse,
                                format!(
                                    "workbook.xml is missing a sheet entry for {}",
                                    worksheet.name
                                ),
                            )
                        })?;
                    writer
                        .write_event(Event::Empty(entry.2.clone()))
                        .map_err(runtime_xml_error)?;
                }
                inside_sheets = false;
                writer
                    .write_event(Event::End(element.into_owned()))
                    .map_err(runtime_xml_error)?;
            }
            Ok(Event::Text(_)) | Ok(Event::CData(_)) | Ok(Event::Comment(_)) if inside_sheets => {}
            Ok(Event::Eof) => break,
            Ok(event) if skip_sheet_depth == 0 => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn read_workbook_sheet_entry_identity(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
) -> OmResult<(SheetId, Option<String>, BytesStart<'static>)> {
    let mut parsed_sheet_id = None::<SheetId>;
    let mut relationship_id = None::<String>;
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        match attr.key.as_ref() {
            b"sheetId" => {
                parsed_sheet_id = value.parse::<u64>().ok().map(SheetId);
            }
            b"r:id" => {
                relationship_id = Some(value);
            }
            _ => {}
        }
    }
    Ok((
        parsed_sheet_id.ok_or_else(|| {
            OmError::new(
                OmErrorCode::Parse,
                "workbook.xml sheet entry is missing a valid sheetId",
            )
        })?,
        relationship_id,
        element.to_owned(),
    ))
}

fn strip_workbook_sheet_entry(
    workbook_xml: &[u8],
    sheet_id: SheetId,
    relationship_id: Option<&str>,
) -> OmResult<Vec<u8>> {
    let mut reader = Reader::from_reader(Cursor::new(workbook_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut skip_depth = 0usize;

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(_)) if skip_depth > 0 => {
                skip_depth += 1;
            }
            Ok(Event::End(_)) if skip_depth > 0 => {
                skip_depth -= 1;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"sheet"
                    && should_strip_workbook_sheet(
                        &element,
                        reader.decoder(),
                        sheet_id,
                        relationship_id,
                    )? => {}
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"sheet"
                    && should_strip_workbook_sheet(
                        &element,
                        reader.decoder(),
                        sheet_id,
                        relationship_id,
                    )? =>
            {
                skip_depth = 1;
            }
            Ok(Event::Eof) => break,
            Ok(event) if skip_depth == 0 => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn should_strip_workbook_sheet(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    sheet_id: SheetId,
    relationship_id: Option<&str>,
) -> OmResult<bool> {
    let mut matches_sheet_id = false;
    let mut matches_relationship_id = false;
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        match attr.key.as_ref() {
            b"sheetId" => {
                matches_sheet_id = value.parse::<u64>().ok() == Some(sheet_id.0);
            }
            b"r:id" => {
                matches_relationship_id = relationship_id == Some(value.as_str());
            }
            _ => {}
        }
    }
    Ok(matches_sheet_id || matches_relationship_id)
}

fn strip_relationship_entries_by_id(
    rels_xml: &[u8],
    relationship_ids: &[String],
) -> OmResult<Vec<u8>> {
    let relationship_ids = relationship_ids
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let mut reader = Reader::from_reader(Cursor::new(rels_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut skip_depth = 0usize;

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(_)) if skip_depth > 0 => {
                skip_depth += 1;
            }
            Ok(Event::End(_)) if skip_depth > 0 => {
                skip_depth -= 1;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship"
                    && should_strip_relationship_entry(
                        &element,
                        reader.decoder(),
                        &relationship_ids,
                    )? => {}
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship"
                    && should_strip_relationship_entry(
                        &element,
                        reader.decoder(),
                        &relationship_ids,
                    )? =>
            {
                skip_depth = 1;
            }
            Ok(Event::Eof) => break,
            Ok(event) if skip_depth == 0 => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn strip_relationship_entries_by_type_or_target(
    rels_xml: &[u8],
    relationship_types: &[&str],
    relationship_targets: &[&str],
) -> OmResult<Vec<u8>> {
    let relationship_types = relationship_types.iter().copied().collect::<BTreeSet<_>>();
    let relationship_targets = relationship_targets
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let mut reader = Reader::from_reader(Cursor::new(rels_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut skip_depth = 0usize;

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(_)) if skip_depth > 0 => {
                skip_depth += 1;
            }
            Ok(Event::End(_)) if skip_depth > 0 => {
                skip_depth -= 1;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship"
                    && should_strip_relationship_entry_by_type_or_target(
                        &element,
                        reader.decoder(),
                        &relationship_types,
                        &relationship_targets,
                    )? => {}
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"Relationship"
                    && should_strip_relationship_entry_by_type_or_target(
                        &element,
                        reader.decoder(),
                        &relationship_types,
                        &relationship_targets,
                    )? =>
            {
                skip_depth = 1;
            }
            Ok(Event::Eof) => break,
            Ok(event) if skip_depth == 0 => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn should_strip_relationship_entry(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    relationship_ids: &BTreeSet<&str>,
) -> OmResult<bool> {
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        if attr.key.as_ref() != b"Id" {
            continue;
        }
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        if relationship_ids.contains(value.as_str()) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn should_strip_relationship_entry_by_type_or_target(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    relationship_types: &BTreeSet<&str>,
    relationship_targets: &BTreeSet<&str>,
) -> OmResult<bool> {
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        match attr.key.as_ref() {
            b"Type" if relationship_types.contains(value.as_str()) => return Ok(true),
            b"Target" => {
                if relationship_targets.contains(value.trim_start_matches('/'))
                    || relationship_targets.iter().any(|target| {
                        value.ends_with(target)
                            && value.len() > target.len()
                            && value.as_bytes()[value.len() - target.len() - 1] == b'/'
                    })
                {
                    return Ok(true);
                }
            }
            _ => {}
        }
    }
    Ok(false)
}

fn strip_content_type_overrides(
    content_types_xml: &[u8],
    part_names: &[String],
) -> OmResult<Vec<u8>> {
    let part_names = part_names
        .iter()
        .map(|part_name| format!("/{}", part_name.trim_start_matches('/')))
        .collect::<BTreeSet<_>>();
    let mut reader = Reader::from_reader(Cursor::new(content_types_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut skip_depth = 0usize;

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(_)) if skip_depth > 0 => {
                skip_depth += 1;
            }
            Ok(Event::End(_)) if skip_depth > 0 => {
                skip_depth -= 1;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Override"
                    && should_strip_content_type_override(
                        &element,
                        reader.decoder(),
                        &part_names,
                    )? => {}
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"Override"
                    && should_strip_content_type_override(
                        &element,
                        reader.decoder(),
                        &part_names,
                    )? =>
            {
                skip_depth = 1;
            }
            Ok(Event::Eof) => break,
            Ok(event) if skip_depth == 0 => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn should_strip_content_type_override(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    part_names: &BTreeSet<String>,
) -> OmResult<bool> {
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        if attr.key.as_ref() != b"PartName" {
            continue;
        }
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        if part_names.contains(value.as_str()) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn strip_content_type_defaults_by_content_type(
    content_types_xml: &[u8],
    content_types: &[&str],
) -> OmResult<Vec<u8>> {
    let content_types = content_types.iter().copied().collect::<BTreeSet<_>>();
    let mut reader = Reader::from_reader(Cursor::new(content_types_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
    let mut buffer = Vec::new();
    let mut skip_depth = 0usize;

    loop {
        match reader.read_event_into(&mut buffer) {
            Ok(Event::Start(_)) if skip_depth > 0 => {
                skip_depth += 1;
            }
            Ok(Event::End(_)) if skip_depth > 0 => {
                skip_depth -= 1;
            }
            Ok(Event::Empty(element))
                if xml_local_name(element.name().as_ref()) == b"Default"
                    && should_strip_content_type_default(
                        &element,
                        reader.decoder(),
                        &content_types,
                    )? => {}
            Ok(Event::Start(element))
                if xml_local_name(element.name().as_ref()) == b"Default"
                    && should_strip_content_type_default(
                        &element,
                        reader.decoder(),
                        &content_types,
                    )? =>
            {
                skip_depth = 1;
            }
            Ok(Event::Eof) => break,
            Ok(event) if skip_depth == 0 => writer
                .write_event(event.into_owned())
                .map_err(runtime_xml_error)?,
            Ok(_) => {}
            Err(error) => return Err(runtime_xml_error(error)),
        }
        buffer.clear();
    }

    Ok(writer.into_inner().into_inner())
}

fn should_strip_content_type_default(
    element: &BytesStart<'_>,
    decoder: quick_xml::encoding::Decoder,
    content_types: &BTreeSet<&str>,
) -> OmResult<bool> {
    for attr in element.attributes() {
        let attr = attr.map_err(runtime_xml_error)?;
        if attr.key.as_ref() != b"ContentType" {
            continue;
        }
        let value = attr
            .decode_and_unescape_value(decoder)
            .map_err(runtime_xml_error)?
            .into_owned();
        if content_types.contains(value.as_str()) {
            return Ok(true);
        }
    }
    Ok(false)
}

pub fn supports_format(format: FileFormat) -> bool {
    matches!(
        format,
        FileFormat::Xlsx | FileFormat::Xlsm | FileFormat::Xltx | FileFormat::Xltm
    )
}

fn blank_workbook_bytes() -> Vec<u8> {
    let package = OpcPackage::new(vec![
        OpcPart {
            name: CONTENT_TYPES_PART_NAME.to_string(),
            content_type: None,
            compression: CompressionMethod::Stored,
            bytes: br#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
</Types>"#
                .to_vec(),
        },
        OpcPart {
            name: "_rels/.rels".to_string(),
            content_type: None,
            compression: CompressionMethod::Stored,
            bytes: br#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>"#
                .to_vec(),
        },
        OpcPart {
            name: WORKBOOK_PART_NAME.to_string(),
            content_type: None,
            compression: CompressionMethod::Stored,
            bytes: br#"<?xml version="1.0" encoding="UTF-8"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"
 xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheets>
    <sheet name="Sheet1" sheetId="1" r:id="rId1"/>
  </sheets>
</workbook>"#
                .to_vec(),
        },
        OpcPart {
            name: WORKBOOK_RELS_PART_NAME.to_string(),
            content_type: None,
            compression: CompressionMethod::Stored,
            bytes: br#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
</Relationships>"#
                .to_vec(),
        },
        OpcPart {
            name: "xl/worksheets/sheet1.xml".to_string(),
            content_type: None,
            compression: CompressionMethod::Stored,
            bytes: blank_worksheet_xml_bytes(),
        },
    ]);

    package.to_bytes().expect("blank workbook package bytes")
}

