fn chart_type_is_volume_stock(chart_type: &ChartType) -> bool {
    matches!(chart_type, ChartType::StockVHLC | ChartType::StockVOHLC)
}

fn volume_stock_series_count(chart_type: &ChartType) -> Option<usize> {
    match chart_type {
        ChartType::StockVHLC => Some(4),
        ChartType::StockVOHLC => Some(5),
        _ => None,
    }
}

fn chart_type_for_axis_group(
    chart: &ChartModel,
    axis_group: ChartAxisGroup,
) -> ChartType {
    match (&chart.chart_type, axis_group) {
        (ChartType::StockVHLC | ChartType::StockVOHLC, ChartAxisGroup::Primary) => {
            ChartType::Column
        }
        (ChartType::StockVHLC, ChartAxisGroup::Secondary) => ChartType::StockHLC,
        (ChartType::StockVOHLC, ChartAxisGroup::Secondary) => ChartType::StockOHLC,
        _ => chart.chart_type.clone(),
    }
}

fn chart_type_for_series(chart: &ChartModel, series: &SeriesModel) -> ChartType {
    if chart_group_overlay_is_stable(chart)
        && let Some(raw_index) = series.raw_index
        && let Some(group) = chart
            .groups
            .iter()
            .find(|group| group.series_raw_indices.contains(&raw_index))
    {
        return group.chart_type.clone();
    }
    chart_type_for_axis_group(chart, series.axis_group)
}

fn series_collection_indices(
    chart: &ChartModel,
    axis_group_filter: Option<ChartAxisGroup>,
    group_index_filter: Option<usize>,
    full: bool,
) -> Vec<usize> {
    let group_raw_indices = group_index_filter
        .and_then(|group_index| chart.groups.get(group_index))
        .map(|group| group.series_raw_indices.iter().copied().collect::<BTreeSet<_>>());
    let mut indices = chart
        .series
        .iter()
        .enumerate()
        .filter_map(|(series_index, series)| {
            ((full || !series.is_filtered)
                && group_raw_indices.as_ref().map_or_else(
                    || {
                        axis_group_filter
                            .map(|axis_group| series.axis_group == axis_group)
                            .unwrap_or(true)
                    },
                    |raw_indices| {
                        series
                            .raw_index
                            .is_some_and(|raw_index| raw_indices.contains(&raw_index))
                    },
                ))
            .then_some(series_index)
        })
        .collect::<Vec<_>>();
    if full {
        indices.sort_by_key(|series_index| {
            (
                chart.series[*series_index]
                    .order
                    .unwrap_or(*series_index as u32),
                *series_index,
            )
        });
    }
    indices
}

fn next_chart_series_raw_index(chart: &ChartModel) -> OmResult<u32> {
    let next = chart
        .series
        .iter()
        .filter_map(|series| series.raw_index)
        .max()
        .map(|index| index.checked_add(1))
        .unwrap_or(Some(0));
    next.ok_or_else(|| OmError::invalid_argument("chart series index space is exhausted"))
}

