fn default_chart_axes() -> Vec<AxisModel> {
    let mut axes = vec![
        default_chart_axis(Some("10".to_string()), ChartAxisKind::Category),
        default_chart_axis(Some("20".to_string()), ChartAxisKind::Value),
    ];
    reconcile_chart_axis_crossings(&mut axes);
    axes
}

fn default_chart_axes_for_type(chart_type: &ChartType) -> Vec<AxisModel> {
    if !chart_type_has_axes(chart_type) {
        return Vec::new();
    }
    if matches!(
        chart_type,
        ChartType::Scatter
            | ChartType::ScatterLines
            | ChartType::ScatterLinesNoMarkers
            | ChartType::ScatterSmooth
            | ChartType::ScatterSmoothNoMarkers
            | ChartType::Bubble
            | ChartType::Bubble3DEffect
    ) {
        let mut axes = vec![
            default_chart_axis(Some("10".to_string()), ChartAxisKind::Value),
            default_chart_axis(Some("20".to_string()), ChartAxisKind::Value),
        ];
        axes[0].cross_axis_raw_id = Some("20".to_string());
        axes[1].cross_axis_raw_id = Some("10".to_string());
        return axes;
    }
    default_chart_axes()
}

fn default_chart_axis(raw_id: Option<String>, kind: ChartAxisKind) -> AxisModel {
    AxisModel {
        raw_id,
        cross_axis_raw_id: None,
        deleted: None,
        kind,
        axis_group: ChartAxisGroup::Primary,
        title: None,
        has_major_gridlines: None,
        has_minor_gridlines: None,
        major_tick_mark: None,
        minor_tick_mark: None,
        tick_label_position: None,
        tick_label_number_format: None,
        tick_label_number_format_linked: None,
        tick_label_spacing: None,
        tick_mark_spacing: None,
        axis_between_categories: None,
        category_type_auto: None,
        base_unit: None,
        major_unit_scale: None,
        minor_unit_scale: None,
        display_unit: None,
        has_display_unit_label: None,
        display_unit_label: None,
        reverse_plot_order: None,
        scale_type: None,
        log_base: None,
        crosses: None,
        crosses_at: None,
        minimum_scale: None,
        maximum_scale: None,
        major_unit: None,
        minor_unit: None,
    }
}

fn ensure_chart_axis(
    chart: &mut ChartModel,
    kind: ChartAxisKind,
    axis_group: ChartAxisGroup,
    preferred_axis_id: u32,
) -> bool {
    if let Some(axis) = chart.axes.iter_mut().find(|axis| {
        axis.axis_group == axis_group
            && (axis.kind == kind
                || (matches!(kind, ChartAxisKind::Category | ChartAxisKind::Date)
                    && matches!(axis.kind, ChartAxisKind::Category | ChartAxisKind::Date)))
    }) {
        if axis.deleted == Some(true) {
            axis.deleted = Some(false);
            return true;
        }
        return false;
    }
    let axis_id = next_chart_axis_raw_id(chart, preferred_axis_id);
    let mut axis = default_chart_axis(Some(axis_id), kind);
    axis.axis_group = axis_group;
    chart.axes.push(axis);
    true
}

fn next_chart_axis_raw_id(chart: &ChartModel, preferred_axis_id: u32) -> String {
    let used_axis_ids = chart
        .axes
        .iter()
        .filter_map(|axis| axis.raw_id.as_deref())
        .collect::<BTreeSet<_>>();
    let mut axis_id = preferred_axis_id;
    while used_axis_ids.contains(axis_id.to_string().as_str()) {
        axis_id += 10;
    }
    axis_id.to_string()
}

fn reconcile_chart_axis_crossings(axes: &mut [AxisModel]) -> bool {
    let mut changed = false;
    for axis_index in 0..axes.len() {
        let target = chart_axis_cross_target_id(axes, &axes[axis_index]);
        if axes[axis_index].cross_axis_raw_id != target {
            axes[axis_index].cross_axis_raw_id = target;
            changed = true;
        }
    }
    changed
}

fn chart_axis_cross_target_id(axes: &[AxisModel], axis: &AxisModel) -> Option<String> {
    if let Some(axis_id) = axis.cross_axis_raw_id.as_ref()
        && axes
            .iter()
            .any(|candidate| candidate.raw_id.as_ref() == Some(axis_id))
    {
        return Some(axis_id.clone());
    }
    match axis.kind {
        ChartAxisKind::Value => axes
            .iter()
            .find(|candidate| {
                candidate.axis_group == axis.axis_group
                    && matches!(candidate.kind, ChartAxisKind::Category | ChartAxisKind::Date)
            })
            .or_else(|| {
                axes.iter().find(|candidate| {
                    candidate.axis_group == ChartAxisGroup::Primary
                        && matches!(candidate.kind, ChartAxisKind::Category | ChartAxisKind::Date)
                })
            }),
        ChartAxisKind::Category | ChartAxisKind::Date | ChartAxisKind::Series => axes
            .iter()
            .find(|candidate| {
                candidate.axis_group == axis.axis_group
                    && candidate.kind == ChartAxisKind::Value
            })
            .or_else(|| {
                axes.iter().find(|candidate| {
                    candidate.axis_group == ChartAxisGroup::Primary
                        && candidate.kind == ChartAxisKind::Value
                })
            })
            .or_else(|| {
                axes
                    .iter()
                    .find(|candidate| candidate.kind == ChartAxisKind::Value)
            }),
    }
    .and_then(|target| target.raw_id.clone())
}

fn normalize_volume_stock_chart(chart: &mut ChartModel) -> bool {
    if !chart_type_is_volume_stock(&chart.chart_type) {
        return false;
    }
    let mut ordered_series = chart
        .series
        .iter()
        .enumerate()
        .map(|(index, series)| (series.order.unwrap_or(index as u32), index))
        .collect::<Vec<_>>();
    ordered_series.sort_by_key(|(order, index)| (*order, *index));
    let volume_series_index = ordered_series.first().map(|(_, index)| *index);
    let mut changed = false;
    for (series_index, series) in chart.series.iter_mut().enumerate() {
        let axis_group = if Some(series_index) == volume_series_index {
            ChartAxisGroup::Primary
        } else {
            ChartAxisGroup::Secondary
        };
        if series.axis_group != axis_group {
            series.axis_group = axis_group;
            changed = true;
        }
    }
    changed |= ensure_chart_axis(
        chart,
        ChartAxisKind::Category,
        ChartAxisGroup::Primary,
        10,
    );
    changed |= ensure_chart_axis(chart, ChartAxisKind::Value, ChartAxisGroup::Primary, 20);
    changed |= ensure_chart_axis(
        chart,
        ChartAxisKind::Value,
        ChartAxisGroup::Secondary,
        50,
    );
    changed |= reconcile_chart_axis_crossings(&mut chart.axes);
    changed
}

fn reconcile_loaded_volume_stock_group_membership(chart: &mut ChartModel) -> OmResult<()> {
    if !chart_type_is_volume_stock(&chart.chart_type) || chart.groups.is_empty() {
        return Ok(());
    }
    let expected_series_count = volume_stock_series_count(&chart.chart_type)
        .expect("volume-stock chart types have a fixed series count");
    if chart.series.len() != expected_series_count {
        return Err(OmError::invalid_argument(format!(
            "loaded volume-stock SetSourceData requires exactly {expected_series_count} series"
        )));
    }
    if chart.groups.len() != 2
        || chart.groups[0].axis_group != ChartAxisGroup::Primary
        || chart.groups[1].axis_group != ChartAxisGroup::Secondary
        || chart.groups[0].chart_type != ChartType::Column
        || !matches!(
            chart.groups[1].chart_type,
            ChartType::StockHLC | ChartType::StockOHLC
        )
    {
        return Err(OmError::unsupported(
            "loaded volume-stock chart group topology is not recognized",
        ));
    }
    let membership = chart
        .series
        .iter()
        .map(|series| {
            let raw_index = series.raw_index.ok_or_else(|| {
                OmError::new(
                    OmErrorCode::InvalidState,
                    "loaded volume-stock series has no stable c:idx identity",
                )
            })?;
            Ok((series.axis_group, raw_index))
        })
        .collect::<OmResult<Vec<_>>>()?;
    for group in &mut chart.groups {
        group.series_raw_indices.clear();
    }
    for (axis_group, raw_index) in membership {
        let group_index = match axis_group {
            ChartAxisGroup::Primary => 0,
            ChartAxisGroup::Secondary => 1,
        };
        chart.groups[group_index].series_raw_indices.push(raw_index);
    }
    chart.series_topology_dirty = true;
    Ok(())
}

fn chart_object_placement_value(placement: &ObjectPlacement) -> OmResult<i32> {
    match placement {
        ObjectPlacement::MoveAndSize => Ok(XL_MOVE_AND_SIZE),
        ObjectPlacement::MoveOnly => Ok(XL_MOVE),
        ObjectPlacement::FreeFloating => Ok(XL_FREE_FLOATING),
        ObjectPlacement::Unknown => Err(OmError::unsupported(
            "ChartObject.Placement is unavailable for unknown drawing placement",
        )),
    }
}

fn chart_source_expr_for_range(
    workbook_id: WorkbookId,
    sheet_id: SheetId,
    rect: Rect,
    worksheet_name: &str,
) -> OmResult<ChartSourceExpr> {
    chart_source_expr_for_range_areas(
        workbook_id,
        vec![(sheet_id, rect, worksheet_name.to_string())],
    )
}

fn chart_source_expr_for_range_areas(
    workbook_id: WorkbookId,
    areas: Vec<(SheetId, Rect, String)>,
) -> OmResult<ChartSourceExpr> {
    let mut raw_parts = Vec::with_capacity(areas.len());
    let mut range_areas = Vec::with_capacity(areas.len());
    for (sheet_id, rect, worksheet_name) in areas {
        raw_parts.push(format!(
            "{}{}",
            formula_sheet_address_qualifier(&worksheet_name),
            format_rect_address_with_flags(rect, true, true)
        ));
        range_areas.push(RangeArea::new(SheetScope::Single(sheet_id), rect)?);
    }

    Ok(ChartSourceExpr {
        raw: FormulaSource {
            text: raw_parts.join(","),
            is_r1c1: false,
        },
        resolved: Some(ReferenceTarget::Range(RangeSet::new(
            workbook_id,
            range_areas,
        )?)),
        full_reference: None,
        cache: None,
        dirty: true,
    })
}

fn chart_source_expr_text(source: Option<&excel_model::ChartSourceExpr>) -> Option<String> {
    source.map(|source| {
        if source.raw.text.starts_with('=') {
            source.raw.text.clone()
        } else {
            format!("={}", source.raw.text)
        }
    })
}

fn series_formula_text(series: &SeriesModel, series_index: usize) -> String {
    let formula_arg_text = |source: Option<&excel_model::ChartSourceExpr>| {
        source.map(|source| {
            let text = source.raw.text.trim_start_matches('=').to_string();
            let mut in_string = false;
            let mut in_quote = false;
            let mut depth = 0usize;
            let mut has_top_level_comma = false;
            let mut chars = text.chars().peekable();
            while let Some(ch) = chars.next() {
                match ch {
                    '"' if !in_quote => {
                        if in_string && chars.peek() == Some(&'"') {
                            chars.next();
                        } else {
                            in_string = !in_string;
                        }
                    }
                    '\'' if !in_string => {
                        if in_quote && chars.peek() == Some(&'\'') {
                            chars.next();
                        } else {
                            in_quote = !in_quote;
                        }
                    }
                    '(' | '{' if !in_string && !in_quote => depth += 1,
                    ')' | '}' if !in_string && !in_quote && depth > 0 => depth -= 1,
                    ',' if !in_string && !in_quote && depth == 0 => {
                        has_top_level_comma = true;
                        break;
                    }
                    _ => {}
                }
            }
            if has_top_level_comma {
                format!("({text})")
            } else {
                text
            }
        })
    };
    let name = formula_arg_text(series.name.as_ref()).unwrap_or_default();
    let x_values = formula_arg_text(series.x_values.as_ref()).unwrap_or_default();
    let values = formula_arg_text(series.values.as_ref()).unwrap_or_default();
    let order = series_plot_order(series, series_index);
    if let Some(bubble_size) = formula_arg_text(series.bubble_size.as_ref()) {
        format!("=SERIES({name},{x_values},{values},{order},{bubble_size})")
    } else {
        format!("=SERIES({name},{x_values},{values},{order})")
    }
}

fn series_plot_order(series: &SeriesModel, series_index: usize) -> u32 {
    series
        .order
        .map(|order| order + 1)
        .unwrap_or((series_index + 1) as u32)
}

fn update_series_plot_order(
    series: &mut [SeriesModel],
    series_index: usize,
    plot_order: u32,
) -> bool {
    let mut ordered_indices = series
        .iter()
        .enumerate()
        .map(|(index, series)| (series.order.unwrap_or(index as u32), index))
        .collect::<Vec<_>>();
    ordered_indices.sort_by_key(|(order, index)| (*order, *index));
    let Some(current_position) = ordered_indices
        .iter()
        .position(|(_, index)| *index == series_index)
    else {
        return false;
    };
    let target_position = plot_order as usize - 1;
    let moved = ordered_indices.remove(current_position);
    ordered_indices.insert(target_position, moved);

    let mut changed = false;
    for (position, (_, index)) in ordered_indices.into_iter().enumerate() {
        let order = position as u32;
        if series[index].order != Some(order) {
            series[index].order = Some(order);
            changed = true;
        }
    }
    changed
}

fn runtime_object_owner(object: RuntimeObjectKind) -> Option<WorkbookHandle> {
    match object {
        RuntimeObjectKind::Application
        | RuntimeObjectKind::WorksheetFunction
        | RuntimeObjectKind::WorkbooksCollection => None,
        RuntimeObjectKind::Workbook { workbook }
        | RuntimeObjectKind::WorksheetsCollection { workbook, .. }
        | RuntimeObjectKind::Worksheet { workbook, .. }
        | RuntimeObjectKind::Range { workbook, .. }
        | RuntimeObjectKind::Areas { workbook, .. }
        | RuntimeObjectKind::Names { workbook, .. }
        | RuntimeObjectKind::Name { workbook, .. }
        | RuntimeObjectKind::ChartObjects { workbook, .. }
        | RuntimeObjectKind::ChartObject { workbook, .. }
        | RuntimeObjectKind::ShapeRange { workbook, .. }
        | RuntimeObjectKind::Chart { workbook, .. }
        | RuntimeObjectKind::ChartArea { workbook, .. }
        | RuntimeObjectKind::PlotArea { workbook, .. }
        | RuntimeObjectKind::ChartTitle { workbook, .. }
        | RuntimeObjectKind::Legend { workbook, .. }
        | RuntimeObjectKind::LegendEntries { workbook, .. }
        | RuntimeObjectKind::LegendEntry { workbook, .. }
        | RuntimeObjectKind::LegendKey { workbook, .. }
        | RuntimeObjectKind::DataTable { workbook, .. }
        | RuntimeObjectKind::ChartFormat { workbook, .. }
        | RuntimeObjectKind::Adjustments { workbook, .. }
        | RuntimeObjectKind::ChartFormatChild { workbook, .. }
        | RuntimeObjectKind::PictureCrop { workbook, .. }
        | RuntimeObjectKind::Border { workbook, .. }
        | RuntimeObjectKind::DataLabels { workbook, .. }
        | RuntimeObjectKind::LeaderLines { workbook, .. }
        | RuntimeObjectKind::DataLabel { workbook, .. }
        | RuntimeObjectKind::ChartGroups { workbook, .. }
        | RuntimeObjectKind::ChartGroup { workbook, .. }
        | RuntimeObjectKind::ChartGroupLines { workbook, .. }
        | RuntimeObjectKind::CategoryCollection { workbook, .. }
        | RuntimeObjectKind::ChartCategory { workbook, .. }
        | RuntimeObjectKind::Axes { workbook, .. }
        | RuntimeObjectKind::Axis { workbook, .. }
        | RuntimeObjectKind::TickLabels { workbook, .. }
        | RuntimeObjectKind::AxisTitle { workbook, .. }
        | RuntimeObjectKind::DisplayUnitLabel { workbook, .. }
        | RuntimeObjectKind::Gridlines { workbook, .. }
        | RuntimeObjectKind::SeriesCollection { workbook, .. }
        | RuntimeObjectKind::Series { workbook, .. }
        | RuntimeObjectKind::Points { workbook, .. }
        | RuntimeObjectKind::Point { workbook, .. } => Some(workbook),
    }
}

fn runtime_name_scope(scope: RuntimeNamesScope) -> NameScope {
    match scope {
        RuntimeNamesScope::Workbook => NameScope::Workbook,
        RuntimeNamesScope::Worksheet(sheet_id) => NameScope::Worksheet(sheet_id),
    }
}

fn coerce_u32_arg(value: &OmValue, label: &str) -> OmResult<u32> {
    match value {
        OmValue::Number(number) => coerce_positive_index(*number, label),
        _ => Err(OmError::type_mismatch(format!("{label} must be numeric"))),
    }
}

fn chart_axis_group_from_excel_value(value: u32, label: &str) -> OmResult<ChartAxisGroup> {
    match value {
        XL_PRIMARY => Ok(ChartAxisGroup::Primary),
        XL_SECONDARY => Ok(ChartAxisGroup::Secondary),
        _ => Err(OmError::invalid_argument(format!(
            "{label} supports xlPrimary and xlSecondary"
        ))),
    }
}

fn chart_object_z_order_operation(command: &OmValue, surface: &str) -> OmResult<&'static str> {
    let OmValue::Number(command) = command else {
        return Err(OmError::type_mismatch(format!(
            "{surface}.ZOrder expects a numeric MsoZOrderCmd argument"
        )));
    };
    if !command.is_finite()
        || command.fract() != 0.0
        || *command < i32::MIN as f64
        || *command > i32::MAX as f64
    {
        return Err(OmError::invalid_argument(format!(
            "{surface}.ZOrder expects an integral MsoZOrderCmd argument"
        )));
    }
    match *command as i32 {
        MSO_BRING_TO_FRONT => Ok("BringToFront"),
        MSO_SEND_TO_BACK => Ok("SendToBack"),
        MSO_BRING_FORWARD => Ok("BringForward"),
        MSO_SEND_BACKWARD => Ok("SendBackward"),
        MSO_BRING_IN_FRONT_OF_TEXT | MSO_SEND_BEHIND_TEXT => Err(OmError::unsupported(format!(
            "{surface}.ZOrder text wrapping commands are not supported for chart objects"
        ))),
        _ => Err(OmError::invalid_argument(format!(
            "{surface}.ZOrder expects a supported MsoZOrderCmd value"
        ))),
    }
}

fn chart_group_axis_groups(chart: &ChartModel) -> Vec<ChartAxisGroup> {
    if chart_group_overlay_is_stable(chart) {
        return chart
            .groups
            .iter()
            .map(|group| group.axis_group)
            .collect();
    }
    if chart_type_is_volume_stock(&chart.chart_type) {
        return vec![ChartAxisGroup::Primary, ChartAxisGroup::Secondary];
    }
    let mut groups = Vec::new();
    if chart.series.is_empty()
        || chart
            .series
            .iter()
            .any(|series| series.axis_group == ChartAxisGroup::Primary)
    {
        groups.push(ChartAxisGroup::Primary);
    }
    if chart
        .series
        .iter()
        .any(|series| series.axis_group == ChartAxisGroup::Secondary)
    {
        groups.push(ChartAxisGroup::Secondary);
    }
    groups
}

fn chart_group_indices(
    chart: &ChartModel,
    shortcut: Option<ChartGroupShortcutKind>,
) -> Vec<usize> {
    chart_group_axis_groups(chart)
        .iter()
        .enumerate()
        .filter_map(|(index, _)| {
            shortcut
                .is_none_or(|shortcut| {
                    chart_group_chart_type(chart, index)
                        .is_ok_and(|chart_type| {
                            chart_type_matches_group_shortcut(&chart_type, shortcut)
                        })
                })
                .then_some(index)
        })
        .collect()
}

fn chart_type_matches_group_shortcut(
    chart_type: &ChartType,
    shortcut: ChartGroupShortcutKind,
) -> bool {
    match shortcut {
        ChartGroupShortcutKind::Area => matches!(
            chart_type,
            ChartType::Area
                | ChartType::Area3D
                | ChartType::AreaStacked
                | ChartType::Area3DStacked
                | ChartType::AreaStacked100
                | ChartType::Area3DStacked100
        ),
        ChartGroupShortcutKind::Bar => matches!(
            chart_type,
            ChartType::Bar
                | ChartType::Bar3DClustered
                | ChartType::BarStacked
                | ChartType::Bar3DStacked
                | ChartType::BarStacked100
                | ChartType::Bar3DStacked100
                | ChartType::CylinderBarClustered
                | ChartType::CylinderBarStacked
                | ChartType::CylinderBarStacked100
                | ChartType::ConeBarClustered
                | ChartType::ConeBarStacked
                | ChartType::ConeBarStacked100
                | ChartType::PyramidBarClustered
                | ChartType::PyramidBarStacked
                | ChartType::PyramidBarStacked100
        ),
        ChartGroupShortcutKind::Column => matches!(
            chart_type,
            ChartType::Column
                | ChartType::Column3D
                | ChartType::Column3DClustered
                | ChartType::ColumnStacked
                | ChartType::Column3DStacked
                | ChartType::ColumnStacked100
                | ChartType::Column3DStacked100
                | ChartType::CylinderColumn
                | ChartType::CylinderColumnClustered
                | ChartType::CylinderColumnStacked
                | ChartType::CylinderColumnStacked100
                | ChartType::ConeColumn
                | ChartType::ConeColumnClustered
                | ChartType::ConeColumnStacked
                | ChartType::ConeColumnStacked100
                | ChartType::PyramidColumn
                | ChartType::PyramidColumnClustered
                | ChartType::PyramidColumnStacked
                | ChartType::PyramidColumnStacked100
        ),
        ChartGroupShortcutKind::Doughnut => {
            matches!(chart_type, ChartType::Doughnut | ChartType::DoughnutExploded)
        }
        ChartGroupShortcutKind::Line => matches!(
            chart_type,
            ChartType::Line
                | ChartType::Line3D
                | ChartType::LineMarkers
                | ChartType::LineMarkersStacked
                | ChartType::LineMarkersStacked100
                | ChartType::LineStacked
                | ChartType::LineStacked100
        ),
        ChartGroupShortcutKind::Pie => matches!(
            chart_type,
            ChartType::Pie
                | ChartType::Pie3D
                | ChartType::PieExploded
                | ChartType::Pie3DExploded
                | ChartType::PieOfPie
                | ChartType::BarOfPie
        ),
        ChartGroupShortcutKind::Radar => matches!(
            chart_type,
            ChartType::Radar | ChartType::RadarMarkers | ChartType::RadarFilled
        ),
        ChartGroupShortcutKind::Surface => matches!(
            chart_type,
            ChartType::Surface
                | ChartType::SurfaceWireframe
                | ChartType::SurfaceTopView
                | ChartType::SurfaceTopViewWireframe
        ),
        ChartGroupShortcutKind::Scatter => matches!(
            chart_type,
            ChartType::Scatter
                | ChartType::ScatterLines
                | ChartType::ScatterLinesNoMarkers
                | ChartType::ScatterSmooth
                | ChartType::ScatterSmoothNoMarkers
        ),
    }
}

fn chart_group_axis_group(chart: &ChartModel, group_index: usize) -> OmResult<ChartAxisGroup> {
    chart_group_axis_groups(chart)
        .get(group_index)
        .copied()
        .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart group not found"))
}

fn chart_group_chart_type(chart: &ChartModel, group_index: usize) -> OmResult<ChartType> {
    if chart_group_overlay_is_stable(chart)
        && let Some(group) = chart.groups.get(group_index)
    {
        return Ok(group.chart_type.clone());
    }
    Ok(chart_type_for_axis_group(
        chart,
        chart_group_axis_group(chart, group_index)?,
    ))
}

fn chart_group_overlay_is_stable(chart: &ChartModel) -> bool {
    if chart.groups.is_empty() {
        return false;
    }
    let mut series_by_raw_index = BTreeMap::<u32, ChartAxisGroup>::new();
    for series in &chart.series {
        let Some(raw_index) = series.raw_index else {
            return false;
        };
        if series_by_raw_index
            .insert(raw_index, series.axis_group)
            .is_some()
        {
            return false;
        }
    }
    let mut grouped_raw_indices = BTreeSet::new();
    for group in &chart.groups {
        for raw_index in &group.series_raw_indices {
            if !grouped_raw_indices.insert(*raw_index)
                || series_by_raw_index.get(raw_index) != Some(&group.axis_group)
            {
                return false;
            }
        }
    }
    grouped_raw_indices.len() == series_by_raw_index.len()
}

fn chart_group_index_for_series_raw_index(
    chart: &ChartModel,
    raw_index: u32,
) -> OmResult<usize> {
    let mut matches = chart
        .groups
        .iter()
        .enumerate()
        .filter_map(|(group_index, group)| {
            group
                .series_raw_indices
                .contains(&raw_index)
                .then_some(group_index)
        });
    let group_index = matches.next().ok_or_else(|| {
        OmError::new(
            OmErrorCode::InvalidState,
            format!("chart series c:idx {raw_index} has no owning chart group"),
        )
    })?;
    if matches.next().is_some() {
        return Err(OmError::new(
            OmErrorCode::InvalidState,
            format!("chart series c:idx {raw_index} belongs to multiple chart groups"),
        ));
    }
    Ok(group_index)
}

fn resolve_series_insert_group(
    chart: &ChartModel,
    axis_group: ChartAxisGroup,
    requested_group_index: Option<usize>,
) -> OmResult<Option<usize>> {
    if chart.groups.is_empty() {
        return Ok(None);
    }
    if chart_type_is_volume_stock(&chart.chart_type) {
        return Err(OmError::unsupported(
            "loaded volume-stock series topology changes require an atomic cardinality-preserving edit",
        ));
    }
    if !chart_group_overlay_is_stable(chart) {
        return Err(OmError::new(
            OmErrorCode::InvalidState,
            "loaded chart series-to-group partition is inconsistent",
        ));
    }
    let group_index = if let Some(group_index) = requested_group_index {
        let group = chart.groups.get(group_index).ok_or_else(|| {
            OmError::new(OmErrorCode::NotFound, "target chart group not found")
        })?;
        if group.axis_group != axis_group {
            return Err(OmError::invalid_argument(
                "target chart group does not use the requested axis group",
            ));
        }
        group_index
    } else {
        chart
            .groups
            .iter()
            .position(|group| group.axis_group == axis_group)
            .ok_or_else(|| {
                OmError::unsupported(
                    "loaded chart has no existing group for the requested axis group",
                )
            })?
    };
    Ok(Some(group_index))
}

fn attach_series_to_chart_group(chart: &mut ChartModel, group_index: usize, raw_index: u32) {
    let group = &mut chart.groups[group_index];
    if !group.series_raw_indices.contains(&raw_index) {
        group.series_raw_indices.push(raw_index);
        chart.series_topology_dirty = true;
    }
}

fn detach_series_from_chart_group(chart: &mut ChartModel, raw_index: u32) -> OmResult<usize> {
    let group_index = chart_group_index_for_series_raw_index(chart, raw_index)?;
    chart.groups[group_index]
        .series_raw_indices
        .retain(|candidate| *candidate != raw_index);
    chart.series_topology_dirty = true;
    Ok(group_index)
}

fn prune_unreferenced_chart_axes(chart: &mut ChartModel, candidate_axis_ids: &[String]) -> bool {
    let remaining_axis_ids = chart
        .groups
        .iter()
        .flat_map(|group| group.axis_ids.iter())
        .collect::<BTreeSet<_>>();
    let candidate_axis_ids = candidate_axis_ids.iter().collect::<BTreeSet<_>>();
    let axis_count = chart.axes.len();
    chart.axes.retain(|axis| {
        axis.raw_id.as_ref().is_none_or(|axis_id| {
            !candidate_axis_ids.contains(axis_id) || remaining_axis_ids.contains(axis_id)
        })
    });
    let changed = chart.axes.len() != axis_count;
    if changed {
        reconcile_chart_axis_crossings(&mut chart.axes);
    }
    changed
}

fn prune_empty_chart_group(chart: &mut ChartModel, group_index: usize) -> (bool, bool) {
    if chart.groups.len() <= 1
        || chart
            .groups
            .get(group_index)
            .is_none_or(|group| !group.series_raw_indices.is_empty())
        || (chart.groups[group_index].axis_group == ChartAxisGroup::Primary
            && chart
                .groups
                .iter()
                .enumerate()
                .filter(|(index, _)| *index != group_index)
                .all(|(_, group)| group.axis_group == ChartAxisGroup::Secondary))
    {
        return (false, false);
    }
    let removed_group = chart.groups.remove(group_index);
    let axis_topology_changed =
        prune_unreferenced_chart_axes(chart, removed_group.axis_ids.as_slice());
    if chart.groups.len() == 1 {
        let group = chart.groups[0].clone();
        chart.chart_type = group.chart_type;
        chart.vary_by_categories = group.vary_by_categories;
        chart.gap_width = group.gap_width;
        chart.gap_depth = group.gap_depth;
        chart.overlap = group.overlap;
        chart.bar_shape = group.bar_shape;
        chart.has_series_lines = group.has_series_lines;
        chart.has_drop_lines = group.has_drop_lines;
        chart.has_hi_lo_lines = group.has_hi_lo_lines;
        chart.has_up_down_bars = group.has_up_down_bars;
        chart.first_slice_angle = group.first_slice_angle;
        chart.explosion = group.explosion;
        chart.bubble_scale = group.bubble_scale;
        chart.show_negative_bubbles = group.show_negative_bubbles;
        chart.has_3d_shading = group.has_3d_shading;
        chart.doughnut_hole_size = group.doughnut_hole_size;
        chart.second_plot_size = group.second_plot_size;
        chart.size_represents = group.size_represents;
        chart.split_type = group.split_type;
        chart.split_value = group.split_value;
        chart.data_labels = group.data_labels;
    }
    (true, axis_topology_changed)
}

fn ensure_loaded_chart_group_target_axes(
    chart: &mut ChartModel,
    source_group_index: usize,
    axis_group: ChartAxisGroup,
) -> OmResult<(Vec<String>, bool)> {
    let source_group = chart.groups.get(source_group_index).ok_or_else(|| {
        OmError::new(OmErrorCode::NotFound, "source chart group not found")
    })?;
    let source_chart_type = source_group.chart_type.clone();
    if axis_group == ChartAxisGroup::Secondary
        && chart_type_supports_3d_view(&source_chart_type)
    {
        return Err(OmError::invalid_argument(
            "3D chart groups can only use the primary axis group",
        ));
    }
    if !chart_type_has_axes(&source_chart_type) {
        return Err(OmError::unsupported(
            "AxisGroup is unavailable for chart types without axes",
        ));
    }
    let source_axis_ids = source_group.axis_ids.clone();
    let source_axes = source_axis_ids
        .iter()
        .map(|axis_id| {
            chart
                .axes
                .iter()
                .find(|axis| axis.raw_id.as_ref() == Some(axis_id))
                .map(|axis| axis.kind)
                .ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        format!("loaded chart group references unknown axis {axis_id}"),
                    )
                })
        })
        .collect::<OmResult<Vec<_>>>()?;
    let mut axis_topology_changed = false;
    let source_uses_value_axis_pair = chart_type_uses_xy_values(&source_chart_type)
        && source_axes.len() == 2
        && source_axes
            .iter()
            .all(|kind| *kind == ChartAxisKind::Value);
    let target_axis_ids = if source_uses_value_axis_pair {
        let bound_target_value_axis_ids = chart.groups.iter().find_map(|group| {
            (group.axis_group == axis_group
                && group.axis_ids.len() == 2
                && group.axis_ids.iter().all(|axis_id| {
                    chart.axes.iter().any(|axis| {
                        axis.raw_id.as_ref() == Some(axis_id)
                            && axis.axis_group == axis_group
                            && axis.kind == ChartAxisKind::Value
                    })
                }))
            .then(|| group.axis_ids.clone())
        });
        let target_value_axes = chart
            .axes
            .iter()
            .filter(|axis| axis.axis_group == axis_group && axis.kind == ChartAxisKind::Value)
            .collect::<Vec<_>>();
        if let Some(axis_ids) = bound_target_value_axis_ids {
            axis_ids
        } else if target_value_axes.is_empty() {
            let preferred_axis_ids = match axis_group {
                ChartAxisGroup::Primary => [10, 20],
                ChartAxisGroup::Secondary => [40, 50],
            };
            let first_axis_id = next_chart_axis_raw_id(chart, preferred_axis_ids[0]);
            let mut first_axis =
                default_chart_axis(Some(first_axis_id.clone()), ChartAxisKind::Value);
            first_axis.axis_group = axis_group;
            let first_axis_index = chart.axes.len();
            chart.axes.push(first_axis);
            let second_axis_id = next_chart_axis_raw_id(chart, preferred_axis_ids[1]);
            chart.axes[first_axis_index].cross_axis_raw_id = Some(second_axis_id.clone());
            let mut second_axis =
                default_chart_axis(Some(second_axis_id.clone()), ChartAxisKind::Value);
            second_axis.axis_group = axis_group;
            second_axis.cross_axis_raw_id = Some(first_axis_id.clone());
            chart.axes.push(second_axis);
            axis_topology_changed = true;
            reconcile_chart_axis_crossings(&mut chart.axes);
            vec![first_axis_id, second_axis_id]
        } else {
            if target_value_axes.len() != 2 {
                return Err(OmError::unsupported(
                    "moving a loaded XY chart group requires exactly two target value axes",
                ));
            }
            target_value_axes
                .into_iter()
                .map(|axis| {
                    axis.raw_id.clone().ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::InvalidState,
                            "loaded XY target axis has no stable identity",
                        )
                    })
                })
                .collect::<OmResult<Vec<_>>>()?
        }
    } else {
        if source_axes
            .iter()
            .filter(|kind| **kind == ChartAxisKind::Value)
            .count()
            != 1
            || !source_axes
                .iter()
                .any(|kind| matches!(kind, ChartAxisKind::Category | ChartAxisKind::Date))
            || source_axes.contains(&ChartAxisKind::Series)
        {
            return Err(OmError::unsupported(
                "moving a loaded chart group requires one value axis and a category or date axis",
            ));
        }
        let preferred_value_axis_id = match axis_group {
            ChartAxisGroup::Primary => 20,
            ChartAxisGroup::Secondary => 50,
        };
        axis_topology_changed = ensure_chart_axis(
            chart,
            ChartAxisKind::Value,
            axis_group,
            preferred_value_axis_id,
        );
        if axis_topology_changed {
            axis_topology_changed |= reconcile_chart_axis_crossings(&mut chart.axes);
        }
        let target_value_axis_id = chart
            .axes
            .iter()
            .find(|axis| axis.axis_group == axis_group && axis.kind == ChartAxisKind::Value)
            .and_then(|axis| axis.raw_id.clone())
            .ok_or_else(|| {
                OmError::new(
                    OmErrorCode::InvalidState,
                    "target chart axis group has no value axis identity",
                )
            })?;
        source_axis_ids
            .iter()
            .zip(source_axes.iter())
            .map(|(source_axis_id, source_axis_kind)| match source_axis_kind {
                ChartAxisKind::Value => Ok(target_value_axis_id.clone()),
                ChartAxisKind::Category | ChartAxisKind::Date => Ok(chart
                    .axes
                    .iter()
                    .find(|axis| {
                        axis.axis_group == axis_group
                            && (axis.kind == *source_axis_kind
                                || matches!(
                                    (axis.kind, source_axis_kind),
                                    (ChartAxisKind::Category, ChartAxisKind::Date)
                                        | (ChartAxisKind::Date, ChartAxisKind::Category)
                                ))
                    })
                    .and_then(|axis| axis.raw_id.clone())
                    .unwrap_or_else(|| source_axis_id.clone())),
                ChartAxisKind::Series => Err(OmError::unsupported(
                    "moving a loaded target series-axis group is not supported losslessly",
                )),
            })
            .collect::<OmResult<Vec<_>>>()?
    };
    Ok((target_axis_ids, axis_topology_changed))
}

fn move_series_to_chart_group(
    chart: &mut ChartModel,
    raw_index: u32,
    axis_group: ChartAxisGroup,
) -> OmResult<(bool, bool)> {
    if chart.groups.is_empty() {
        return Ok((false, false));
    }
    if chart_type_is_volume_stock(&chart.chart_type) {
        return Err(OmError::unsupported(
            "loaded volume-stock series group moves are not supported losslessly",
        ));
    }
    if !chart_group_overlay_is_stable(chart) {
        return Err(OmError::new(
            OmErrorCode::InvalidState,
            "loaded chart series-to-group partition is inconsistent",
        ));
    }
    let source_group_index = chart_group_index_for_series_raw_index(chart, raw_index)?;
    if chart.groups[source_group_index].axis_group == axis_group {
        return Ok((false, false));
    }
    let source_chart_type = chart.groups[source_group_index].chart_type.clone();
    let mut axis_topology_changed = false;
    let target_group_index = if let Some(group_index) = chart
        .groups
        .iter()
        .position(|group| group.axis_group == axis_group && group.chart_type == source_chart_type)
    {
        group_index
    } else {
        let (target_axis_ids, changed) =
            ensure_loaded_chart_group_target_axes(chart, source_group_index, axis_group)?;
        axis_topology_changed |= changed;
        let mut new_group = chart.groups[source_group_index].clone();
        new_group.loaded_index = None;
        new_group.axis_group = axis_group;
        new_group.axis_ids = target_axis_ids;
        new_group.series_raw_indices.clear();
        new_group.dirty = true;
        let target_group_index = chart.groups.len();
        chart.groups.push(new_group);
        target_group_index
    };
    detach_series_from_chart_group(chart, raw_index)?;
    attach_series_to_chart_group(chart, target_group_index, raw_index);
    let (group_topology_changed, removed_axes) =
        prune_empty_chart_group(chart, source_group_index);
    Ok((
        axis_topology_changed || removed_axes,
        group_topology_changed,
    ))
}

fn chart_plot_by_from_optional_arg(value: Option<&OmValue>, label: &str) -> OmResult<Option<i32>> {
    match value {
        None => Ok(None),
        Some(value) if om_value_is_omitted(value) => Ok(None),
        Some(OmValue::Number(number)) => {
            if !number.is_finite()
                || number.fract() != 0.0
                || *number < i32::MIN as f64
                || *number > i32::MAX as f64
            {
                return Err(OmError::invalid_argument(format!(
                    "{label} expects an integer value when provided"
                )));
            }
            let plot_by = *number as i32;
            if !matches!(plot_by, XL_PLOT_BY_ROWS | XL_PLOT_BY_COLUMNS) {
                return Err(OmError::invalid_argument(format!(
                    "{label} supports xlRows and xlColumns"
                )));
            }
            Ok(Some(plot_by))
        }
        Some(_) => Err(OmError::type_mismatch(format!(
            "{label} expects a numeric value when provided"
        ))),
    }
}

fn coerce_i32_arg(value: &OmValue, label: impl AsRef<str>) -> OmResult<i32> {
    let label = label.as_ref();
    match value {
        OmValue::Number(number)
            if number.is_finite()
                && number.fract() == 0.0
                && *number >= i32::MIN as f64
                && *number <= i32::MAX as f64 =>
        {
            Ok(*number as i32)
        }
        OmValue::Number(_) => Err(OmError::invalid_argument(format!(
            "{label} must be an integer"
        ))),
        _ => Err(OmError::type_mismatch(format!("{label} must be numeric"))),
    }
}

fn coerce_chart_view_3d_integer(value: &OmValue, member: &str) -> OmResult<i32> {
    let OmValue::Number(number) = value else {
        return Err(OmError::type_mismatch(format!(
            "Chart.{member} expects a numeric value"
        )));
    };
    if !number.is_finite() {
        return Err(OmError::invalid_argument(format!(
            "Chart.{member} expects a finite numeric value"
        )));
    }
    let value = number.round();
    if value < i32::MIN as f64 || value > i32::MAX as f64 {
        return Err(OmError::invalid_argument(format!(
            "Chart.{member} value is out of range"
        )));
    }
    Ok(value as i32)
}

fn coerce_positive_index(value: f64, label: &str) -> OmResult<u32> {
    if !value.is_finite() || value.fract() != 0.0 || value < 1.0 || value > u32::MAX as f64 {
        return Err(OmError::invalid_argument(format!(
            "{label} must be a positive 1-based integer"
        )));
    }
    Ok(value as u32)
}

fn parse_cells_args(args: &[OmValue]) -> OmResult<(u32, u32)> {
    if args.len() != 2 {
        return Err(OmError::invalid_argument(
            "Worksheet.Cells expects row and column arguments",
        ));
    }
    let column = match &args[1] {
        OmValue::Number(number) => {
            let index = coerce_positive_index(*number, "Worksheet.Cells column")?;
            if index > EXCEL_MAX_COLUMN_INDEX {
                return Err(OmError::invalid_argument(
                    "Worksheet.Cells column is out of bounds",
                ));
            }
            index
        }
        OmValue::Text(reference) => {
            let reference = reference.trim().replace('$', "").to_ascii_uppercase();
            if reference.is_empty() || !reference.chars().all(|ch| ch.is_ascii_alphabetic()) {
                return Err(OmError::invalid_argument(
                    "Worksheet.Cells column text selector must be a column label like \"B\"",
                ));
            }

            let mut index = 0u32;
            for ch in reference.bytes() {
                index = index
                    .checked_mul(26)
                    .and_then(|value| value.checked_add((ch - b'A' + 1) as u32))
                    .ok_or_else(|| {
                        OmError::invalid_argument(
                            "Worksheet.Cells column text selector overflows column bounds",
                        )
                    })?;
            }
            if index > EXCEL_MAX_COLUMN_INDEX {
                return Err(OmError::invalid_argument(
                    "Worksheet.Cells column text selector is out of bounds",
                ));
            }
            index
        }
        _ => {
            return Err(OmError::type_mismatch(
                "Worksheet.Cells column must be numeric or a column label string",
            ));
        }
    };
    let row = coerce_u32_arg(&args[0], "Worksheet.Cells row")?;
    if row > EXCEL_MAX_ROW_INDEX {
        return Err(OmError::invalid_argument(
            "Worksheet.Cells row is out of bounds",
        ));
    }
    Ok((row, column))
}

fn coerce_optional_bool_arg(value: &OmValue, default: bool, label: &str) -> OmResult<bool> {
    match value {
        OmValue::Missing | OmValue::Empty | OmValue::Null => Ok(default),
        OmValue::Bool(value) => Ok(*value),
        _ => Err(OmError::type_mismatch(format!(
            "{label} must be boolean when provided"
        ))),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RangeAddressReferenceStyle {
    A1,
    R1C1,
}

fn coerce_optional_reference_style_arg(value: &OmValue) -> OmResult<RangeAddressReferenceStyle> {
    match value {
        OmValue::Missing | OmValue::Empty | OmValue::Null => Ok(RangeAddressReferenceStyle::A1),
        OmValue::Number(number) => {
            if !number.is_finite()
                || number.fract() != 0.0
                || *number < i32::MIN as f64
                || *number > i32::MAX as f64
            {
                return Err(OmError::invalid_argument(
                    "Range.Address ReferenceStyle expects an integral XlReferenceStyle value",
                ));
            }
            match *number as i32 {
                XL_A1 => Ok(RangeAddressReferenceStyle::A1),
                XL_R1C1 => Ok(RangeAddressReferenceStyle::R1C1),
                _ => Err(OmError::invalid_argument(
                    "Range.Address ReferenceStyle supports xlA1 and xlR1C1",
                )),
            }
        }
        _ => Err(OmError::type_mismatch(
            "Range.Address ReferenceStyle expects a numeric XlReferenceStyle value when provided",
        )),
    }
}

fn coerce_evaluate_expression_arg<'a>(args: &'a [OmValue], context: &str) -> OmResult<&'a str> {
    let [value] = args else {
        return Err(OmError::invalid_argument(format!(
            "{context} expects one formula text argument"
        )));
    };
    match value {
        OmValue::Text(expression) => Ok(expression),
        _ => Err(OmError::type_mismatch(format!(
            "{context} expects a formula text argument"
        ))),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FormulaEvalError {
    Unsupported,
    Null,
    Div0,
    Value,
    Ref,
    Name,
    NA,
    Num,
    GettingData,
    Spill,
    Calc,
    Field,
    Blocked,
    Busy,
    Connect,
    Python,
    Timeout,
    Unknown,
}

#[derive(Debug, Clone, PartialEq)]
struct FormulaArrayResult {
    rows: usize,
    cols: usize,
    values: Vec<CellValue>,
}

impl FormulaArrayResult {
    fn single(value: CellValue) -> Self {
        Self {
            rows: 1,
            cols: 1,
            values: vec![value],
        }
    }
}

impl FormulaEvalError {
    fn into_cell_value(self) -> Option<CellValue> {
        match self {
            FormulaEvalError::Unsupported => None,
            FormulaEvalError::Null => Some(CellValue::Error(CellError::Null)),
            FormulaEvalError::Div0 => Some(CellValue::Error(CellError::Div0)),
            FormulaEvalError::Value => Some(CellValue::Error(CellError::Value)),
            FormulaEvalError::Ref => Some(CellValue::Error(CellError::Ref)),
            FormulaEvalError::Name => Some(CellValue::Error(CellError::Name)),
            FormulaEvalError::NA => Some(CellValue::Error(CellError::NA)),
            FormulaEvalError::Num => Some(CellValue::Error(CellError::Num)),
            FormulaEvalError::GettingData => Some(CellValue::Error(CellError::GettingData)),
            FormulaEvalError::Spill => Some(CellValue::Error(CellError::Spill)),
            FormulaEvalError::Calc => Some(CellValue::Error(CellError::Calc)),
            FormulaEvalError::Field => Some(CellValue::Error(CellError::Field)),
            FormulaEvalError::Blocked => Some(CellValue::Error(CellError::Blocked)),
            FormulaEvalError::Busy => Some(CellValue::Error(CellError::Busy)),
            FormulaEvalError::Connect => Some(CellValue::Error(CellError::Connect)),
            FormulaEvalError::Python => Some(CellValue::Error(CellError::Python)),
            FormulaEvalError::Timeout => Some(CellValue::Error(CellError::Timeout)),
            FormulaEvalError::Unknown => Some(CellValue::Error(CellError::Unknown)),
        }
    }
}

fn formula_eval_error_from_cell_error(error: CellError) -> FormulaEvalError {
    match error {
        CellError::Null => FormulaEvalError::Null,
        CellError::Div0 => FormulaEvalError::Div0,
        CellError::Ref => FormulaEvalError::Ref,
        CellError::Name => FormulaEvalError::Name,
        CellError::NA => FormulaEvalError::NA,
        CellError::Num => FormulaEvalError::Num,
        CellError::GettingData => FormulaEvalError::GettingData,
        CellError::Spill => FormulaEvalError::Spill,
        CellError::Calc => FormulaEvalError::Calc,
        CellError::Field => FormulaEvalError::Field,
        CellError::Blocked => FormulaEvalError::Blocked,
        CellError::Busy => FormulaEvalError::Busy,
        CellError::Connect => FormulaEvalError::Connect,
        CellError::Python => FormulaEvalError::Python,
        CellError::Timeout => FormulaEvalError::Timeout,
        CellError::Unknown => FormulaEvalError::Unknown,
        CellError::Value => FormulaEvalError::Value,
    }
}

