                d = 1.0 + aa * d;
                if d.abs() < FLOOR {
                    d = FLOOR;
                }
                c = 1.0 + aa / c;
                if c.abs() < FLOOR {
                    c = FLOOR;
                }
                d = 1.0 / d;
                let delta = d * c;
